select 'pest', 'Pro Shield Pest Control Services LLC', 'Pro Shield Pest Control Services LLC', 'دبي', null, '+97143888235', 'https://www.proshield.ae/', null, 'شركة لمكافحة الحشرات والتعقيم للمنازل والمنشآت التجارية في دبي وأبوظبي والشارقة والعين.', 'https://www.proshield.ae/contact/', 'تقدم بروشيلد خدمات مكافحة الحشرات والتطهير والتعقيم للقطاعين السكني والتجاري، وتغطي دبي وأبوظبي والشارقة والعين. وتذكر أن جميع مهندسيها وفنييها مرخصون من البلدية وأنها تستخدم منتجات معتمدة من البلدية، وتحمل شهادات ISO وعضوية الجمعية الوطنية لإدارة الآفات (NPMA).', 'https://www.proshield.ae/wp-content/uploads/2024/12/Asset-29@2x.png', 'info@proshield.ae', null, null, array['مكافحة الحشرات السكنية والتجارية', 'خدمات التطهير والتعقيم', 'من عملائها: سبينيس', 'من عملائها: دبي الجنوب', 'من عملائها: شوبا العقارية']::text[], 'أسسها ويرأسها لسعد الطرابلسي، ويضم فريقها مهندسين وفنيين مرخصين من البلدية.', true
where not exists (select 1 from public.service_providers where category = 'pest' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Pro Shield Pest Control Services LLC'));
