select 'smart_home', 'Lightrix', 'Lightrix', 'دبي', 'وادي الصفا', '+971 52 319 7391', 'https://www.lightrix.ae/', null, 'شركة في دبي تدمج الإضاءة الذكية والأتمتة وأنظمة السينما المنزلية والتيار الخفيف.', 'https://www.lightrix.ae/', 'تعمل لايتريكس على دمج الإضاءة الذكية والأتمتة لتحسين كفاءة الطاقة والراحة. وتشمل خدماتها غرف السينما والوسائط والإضاءة والستائر والترفيه متعدد الغرف والشبكات وأنظمة الإنذار والمراقبة، وتعمل بأنظمة منها Lutron وCrestron وControl4 وKNX.', 'https://www.lightrix.ae/images/lightrix.png', 'info@lightrix.com', 'سيتي لاند مول، مكتب 271، وادي الصفا 4، بجوار القرية العالمية، دبي', null, array['غرف السينما والوسائط', 'التحكم في الإضاءة والستائر', 'الترفيه متعدد الغرف', 'أنظمة التيار الخفيف', 'أنظمة إدارة المباني']::text[], 'تذكر الشركة أن فريقها يضم أكثر من 15 مختصًا.', true
where not exists (select 1 from public.service_providers where category = 'smart_home' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Lightrix'));
